def test_get_with_filters_on_combined_qs(self):
    qs = Number.objects.all()
    combinators = ['union']
    if connection.features.supports_select_difference:
        combinators.append('difference')
    if connection.features.supports_select_intersection:
        combinators.append('intersection')
    for combinator in combinators:
        combined_qs = getattr(qs, combinator)(qs.filter(num=1))
        msg = 'Calling QuerySet.get(...) with filters after %s() is not supported.' % combinator
        for args, kwargs in (
            ((), {'num': 1}),
            ((Q(num=1),), {}),
            ((Q(num=1),), {'other_num': 9}),
        ):
            with self.subTest(combinator=combinator, args=args, kwargs=kwargs):
                with self.assertRaisesMessage(NotSupportedError, msg):
                    combined_qs.get(*args, **kwargs)

